update roam_territory
set owner_member_id = 0, claim_photo_url = '', claim_request_id = territory_id, status = 'REVOKED'
where owner_member_id = #{memberId}

update roam_territory_audit
set member_id = 0, latitude = null, longitude = null, accuracy_m = null, distance_m = null, detail_json = null
where member_id = #{memberId}
